games=json.load(open(sys.argv[2]));drawn=set(json.load(open(sys.argv[3])))
need=set()
for k,v in games.items():
  for m in v:
    if m[0] not in drawn and m[0]!='Frostling':need.add(m[0])
mp={}
for p in M.replace('\n','').split(';'):
  a,b=p.split('=');mp[a.strip()]=b.strip()
